import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def build(vals):
    head = None
    tail = None
    for v in vals:
        node = N(v)
        if head is None:
            head = node
        else:
            tail.nxt = node
        tail = node
    return head

def to_list(head):
    out = []
    cur = head
    while cur:
        out.append(cur.v)
        cur = cur.nxt
    return out

def reverse_best(head, left, right):
    if not head or left == right:
        return head
    dummy = N(0, head)
    prev = dummy
    for _ in range(left - 1):
        prev = prev.nxt
    cur = prev.nxt
    for _ in range(right - left):
        nxt = cur.nxt
        cur.nxt = nxt.nxt
        nxt.nxt = prev.nxt
        prev.nxt = nxt
    return dummy.nxt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    left = int(data[1])
    right = int(data[2])
    vals = list(map(int, data[3:3 + n]))
    print(' '.join(map(str, to_list(reverse_best(build(vals), left, right)))))
